      "name": "CounterCtrl",
      "desc": "Generates the next count value based on enable and direction, ensuring synchronous operation on clock edges."
    },
    {
      "name": "RegArray",
      "desc": "Stores the current count value and provides it to the output interface; reset is handled asynchronously."
    },
    {
      "name": "OutputRead",
      "desc": "Provides the current count value to the external interface in a synchronized manner."
    }
  ],
  "mermaid": "graph TD\n  In[\"clk\"] --> B[CounterCtrl]\n  B --> C[RegArray]\n  C --> D[OutputRead]"
